read1 :: proc(path: string) -> []u8 {
	b, err := os.read_entire_file_from_path(path, context.allocator)
	if err != nil {
		fmt.eprintfln("sfx_test: cannot read %s", path)
	}
	return b
}

spawn_fx_init :: proc(fx: ^Spawn_FX, allocator := context.allocator) {
	fx^ = {}
	fx.reveals = make([dynamic]Spawn_Reveal, 0, 4, allocator)
}

spawn_fx_destroy :: proc(fx: ^Spawn_FX) {
	delete(fx.reveals)
	fx^ = {}
}
